    const s = keep(ctx, new Tone.MembraneSynth({ pitchDecay: 0.14, octaves: 2.2, oscillator: { type: "triangle" }, envelope: { attack: 0.001, decay: 0.55, sustain: 0, release: 0.1 } })).connect(V("simmons", -0.15));
