    const n = keep(ctx, new Tone.NoiseSynth({ noise: { type: "white" }, envelope: { attack: 0.018, decay: 0.08, sustain: 0, release: 0.04 } })).connect(bp);
    return (t, v) => n.triggerAttackRelease(0.06, t, v);
